function ReportNull(x)
if isempty(x);fprintf(2,'NULL:NOT SENT');end
end
function GetSpockInfo4Tasks(DateNum,ChNum,AreaNum,PairNum,Time)
global AnalysisOpts
if sum(AnalysisOpts.ProcessingStep==[3 4 8])
    AnalysisOpts.Spock_TaskName=AnalysisOpts.CurrentClassifierOpts.Name;
    AnalysisOpts.Spock_ExtraInfo=sprintf('%s-%i-%s-%i-%i-%i',AnalysisOpts.AreaNames{AreaNum},...
        AnalysisOpts.PopulationAna.PSTHbin,AnalysisOpts.SpkCntStartFieldName(1:4),...
        AnalysisOpts.DividSpockClassifier,Time,AnalysisOpts.NTrlStpLearningArea);
end
end
